  t.write_through_invariant_id,                                                 -- Primary key (auto-synthesized: WriteThroughInvariant had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Identifier for this narrative entry (single-row tables use 'primary').
  t.description,                                                                -- The full narrative content for this concept.
  calc_write_through_invariant_description_length(t.write_through_invariant_id) AS description_length,-- Order 1. Character length of the narrative text.
  calc_write_through_invariant_is_substantive(t.write_through_invariant_id) AS is_substantive,-- Order 2. Narrative is at least 200 characters (not a placeholder).
  calc_write_through_invariant_narrative_state(t.write_through_invariant_id) AS narrative_state,-- Order 3. ready / stub.
  calc_write_through_invariant_is_ready(t.write_through_invariant_id) AS is_ready,-- Order 4. Narrative is ready for publication.
  calc_write_through_invariant_section_label(t.write_through_invariant_id) AS section_label-- Order 5. Display label with readiness.
FROM write_through_invariant t;

